fn pairs(set: &JHashSet<VarVersionPair>) -> String {
    if set.iter().next().is_none() {
        return "-".to_string();
    }
    set.iter()
        .map(|p| format!("{}.{}", p.var, p.version))
        .collect::<Vec<_>>()
        .join(",")
}

