// ---- 5. replaceExprent ----

fn repl(label: &str, parent: Exprent, old: Exprent, neu: Exprent) -> String {
    let before = desc(parent);
    let after = guard(|| {
        parent.replace_exprent(old, neu);
        desc(parent)
    });
    l!("repl", label, before, after)
}

fn repl_lines(label: &str) -> Vec<String> {
    reset();
    let line = match label {
        "array" => {
            let x = var(1);
            repl(label, ArrayExprent::new(x, x, int(), None).0, x, ci(9))
        }
        "array_equal_not_identical" => {
            let a = arr(var(1), ci(0), int());
            repl(label, a, var(1), ci(9))
        }
        "assert" => {
            let x = var(1);
            repl(label, assert_of(vec![Some(x), None, Some(x)]), x, ci(9))
        }
        "assignment" => {
            let x = var(1);
            repl(label, asg(x, x), x, ci(9))
        }
        "exit" => {
            let x = var(1);
            repl(label, ret(Some(x), int()), x, ci(9))
        }
        "exit_null" => repl(label, ret(None, VarType::VARTYPE_VOID()), var(1), ci(9)),
        "field" => {
            let x = var(1);
            repl(label, ifield("f", Some(x), "I"), x, var(2))
        }
        "field_static" => repl(label, sfield("f", "I"), var(1), var(2)),
        "function" => {
            let x = var(1);
            repl(label, fn_(FunctionType::Add, vec![x, x]), x, ci(9))
        }
        "function_nested" => {
            let x = var(1);
            repl(
                label,
                fn_(FunctionType::Add, vec![fn_(FunctionType::Neg, vec![x]), x]),
                x,
                ci(9),
            )
        }
        "if_condition" => {
            let ie = ifx(if_exprent::Type::Icmpeq, var(1), var(2));
            repl(label, ie, ie.as_if().get_condition(), var(3))
        }
        "if_nested" => {
            let x = var(1);
            repl(label, ifx(if_exprent::Type::Icmpeq, x, var(2)), x, var(3))
        }
        "invocation" => {
            let x = var(1);
            repl(
                label,
                inv("m", "(II)V", Some(x), vec![x, var(2), x]),
                x,
                ci(9),
            )
        }
        "monitor" => {
            let x = var(1);
            repl(label, monitor(monitor_exprent::Type::Enter, x), x, var(2))
        }
        "new_dims" => {
            let x = var(1);
            repl(
                label,
                new_arr(arr_t(CodeType::Int, 2), vec![x, x], vec![], false),
                x,
                ci(9),
            )
        }
        "new_elems" => {
            let x = var(1);
            repl(
                label,
                new_arr(arr_t(CodeType::Int, 1), vec![], vec![x, ci(1), x], true),
                x,
                ci(9),
            )
        }
        "new_ctor_param" => {
            let x = var(1);
            repl(
                label,
                new_obj("a/B", Some(inv("<init>", "(II)V", None, vec![x, x]))),
                x,
                ci(9),
            )
        }
        "new_ctor_swap" => {
            let c = inv("<init>", "()V", None, vec![]);
            let n = new_obj("a/B", Some(c));
            repl(label, n, c, inv("<init>", "(I)V", None, vec![ci(1)]))
        }
        "new_ctor_badcast" => {
            let c = inv("<init>", "()V", None, vec![]);
            let n = new_obj("a/B", Some(c));
            repl(label, n, c, var(5))
        }
        "switch_head" => {
            let x = var(1);
            let cases = vec![vec![Some(x)]];
            let sh = switch_head(x, cases);
            let line = repl(label, sh, x, var(2));
            let case_ids: Vec<Exprent> = sh
                .as_switch_head()
                .get_case_values()
                .get(0)
                .iter()
                .flatten()
                .collect();
            return vec![line, l!("replsh", label, ids(&case_ids))];
        }
        "yield" => {
            let x = var(1);
            repl(label, yield_of(x, int()), x, var(2))
        }
        "base_annotation" => {
            let x = ci(1);
            repl(label, ann("a/A", &["value"], vec![x]), x, ci(2))
        }
        "base_pattern" => {
            let x = var(1);
            repl(label, pat("a/R", vec![x]), x, var(2))
        }
        "base_const" => repl(label, ci(1), var(1), var(2)),
        "base_var" => {
            let x = var(1);
            repl(label, x, x, var(2))
        }
        "base_switch" => repl(label, switch_of(switch_stat(), true), var(1), var(2)),
        _ => panic!("unknown replaceExprent case {label}"),
    };
    vec![line]
}

fn run_repl(label: &str) {
    let _g = common::install_default_context();
    check_label(&["repl", "replsh"], label, repl_lines(label));
}

cases! { run_repl:
    replace_array => "array",
    replace_array_equal_not_identical => "array_equal_not_identical",
    replace_assert => "assert",
    replace_assignment => "assignment",
    replace_exit => "exit",
    replace_exit_null => "exit_null",
    replace_field => "field",
    replace_field_static => "field_static",
    replace_function => "function",
    replace_function_nested => "function_nested",
    replace_if_condition => "if_condition",
    replace_if_nested => "if_nested",
    replace_invocation => "invocation",
    replace_monitor => "monitor",
    replace_new_dims => "new_dims",
    replace_new_elems => "new_elems",
    replace_new_ctor_param => "new_ctor_param",
    replace_new_ctor_swap => "new_ctor_swap",
    replace_new_ctor_badcast => "new_ctor_badcast",
    replace_switch_head => "switch_head",
    replace_yield => "yield",
    replace_base_annotation => "base_annotation",
    replace_base_pattern => "base_pattern",
    replace_base_const => "base_const",
    replace_base_var => "base_var",
    replace_base_switch => "base_switch",
}

