const CONST_LABELS: [&str; 48] = [
    "b0",
    "b1",
    "i0",
    "i1",
    "im1",
    "i97",
    "i200",
    "im200",
    "i40000",
    "i70000",
    "imin",
    "imax",
    "int1",
    "char97",
    "l0",
    "l1",
    "lm1",
    "lmin",
    "l2p40",
    "l2p32p1",
    "f0",
    "fm0",
    "f1",
    "f15",
    "fnan",
    "fnan2",
    "finf",
    "d0",
    "dm0",
    "d1",
    "dnan",
    "dinf",
    "dmin",
    "d1e300",
    "s_empty",
    "s_a",
    "s_a2",
    "s_uni",
    "s_null",
    "null",
    "null2",
    "int_long1",
    "long_int1",
    "double_float1",
    "class_str",
    "class_arr",
    "class_null",
    "int_null",
];

fn const_subject(label: &str) -> ConstExprent {
    use ConstValue::{Double, Float, Int, Long};
    let float = VarType::VARTYPE_FLOAT;
    let double = VarType::VARTYPE_DOUBLE;
    let e = match label {
        "b0" => cb(0),
        "b1" => cb(1),
        "i0" => ci(0),
        "i1" => ci(1),
        "im1" => ci(-1),
        "i97" => ci(97),
        "i200" => ci(200),
        "im200" => ci(-200),
        "i40000" => ci(40000),
        "i70000" => ci(70000),
        "imin" => ci(i32::MIN),
        "imax" => ci(i32::MAX),
        "int1" => ct(int(), Some(Int(1))),
        "char97" => ct(VarType::VARTYPE_CHAR(), Some(Int(97))),
        "l0" => ct(long(), Some(Long(0))),
        "l1" => ct(long(), Some(Long(1))),
        "lm1" => ct(long(), Some(Long(-1))),
        "lmin" => ct(long(), Some(Long(i64::MIN))),
        "l2p40" => ct(long(), Some(Long(1i64 << 40))),
        "l2p32p1" => ct(long(), Some(Long((1i64 << 32) + 1))),
        "f0" => ct(float(), Some(Float(0.0))),
        "fm0" => ct(float(), Some(Float(-0.0))),
        "f1" => ct(float(), Some(Float(1.0))),
        "f15" => ct(float(), Some(Float(1.5))),
        "fnan" => ct(float(), Some(Float(f32::NAN))),
        "fnan2" => ct(float(), Some(Float(f32::from_bits(0x7fc0_0001)))),
        "finf" => ct(float(), Some(Float(f32::INFINITY))),
        "d0" => ct(double(), Some(Double(0.0))),
        "dm0" => ct(double(), Some(Double(-0.0))),
        "d1" => ct(double(), Some(Double(1.0))),
        "dnan" => ct(double(), Some(Double(f64::NAN))),
        "dinf" => ct(double(), Some(Double(f64::NEG_INFINITY))),
        "dmin" => ct(double(), Some(Double(f64::from_bits(1)))),
        "d1e300" => ct(double(), Some(Double(1e300))),
        "s_empty" => cs(""),
        "s_a" => cs("a"),
        "s_a2" => cs("a"),
        "s_uni" => cs("\u{e9}\u{4e2d}\u{1f600}"),
        "s_null" => ct(VarType::VARTYPE_STRING(), None),
        "null" => ct(VarType::VARTYPE_NULL(), None),
        "null2" => ct(VarType::VARTYPE_NULL(), None),
        "int_long1" => ct(int(), Some(Long(1))),
        "long_int1" => ct(long(), Some(Int(1))),
        "double_float1" => ct(double(), Some(Float(1.0))),
        "class_str" => ct(VarType::VARTYPE_CLASS(), Some("java/lang/String".into())),
        "class_arr" => ct(VarType::VARTYPE_CLASS(), Some("[I".into())),
        "class_null" => ct(VarType::VARTYPE_CLASS(), None),
        "int_null" => ct(int(), None),
        _ => panic!("unknown const case {label}"),
    };
    e.as_const()
}

fn all_consts() -> Vec<ConstExprent> {
    reset();
    CONST_LABELS.iter().map(|l| const_subject(l)).collect()
}

