// ---- bytecode ranges ----

fn cbc(v: i32, b: &[usize]) -> Exprent {
    ConstExprent::new_int(v, false, Some(&bs(b))).0
}

fn vbc(index: i32, b: &[usize]) -> Exprent {
    VarExprent::new_bytecode(index, Some(int()), None, Some(&bs(b))).0
}

fn bcr_subject(label: &str) -> Exprent {
    match label {
        "assignment" => AssignmentExprent::new(vbc(1, &[1]), cbc(2, &[2]), Some(&bs(&[3]))).0,
        "array" => ArrayExprent::new(vbc(1, &[4]), cbc(0, &[5]), int(), Some(&bs(&[6]))).0,
        "function" => {
            FunctionExprent::new(
                FunctionType::Add,
                vec![
                    vbc(1, &[1]),
                    FunctionExprent::new_single(FunctionType::Neg, vbc(2, &[9]), Some(&bs(&[10])))
                        .0,
                ],
                Some(&bs(&[11])),
            )
            .0
        }
        "if" => {
            IfExprent::new(
                if_exprent::Type::Icmpeq,
                &mut stack_of(vec![vbc(1, &[0]), vbc(2, &[1])]),
                Some(&bs(&[2])),
            )
            .0
        }
        "invocation" => {
            let ie = inv("m", "(I)V", Some(vbc(1, &[3])), vec![cbc(1, &[4])]);
            ie.add_bytecode_offsets(Some(&bs(&[5])));
            ie
        }
        "new_array" => {
            let n = NewExprent::new(arr_t(CodeType::Int, 1), vec![cbc(2, &[1])], Some(&bs(&[2])));
            n.set_lst_array_elements(vec![cbc(1, &[3]), cbc(2, &[4])]);
            n.0
        }
        "new_object" => {
            let c = inv("<init>", "(I)V", None, vec![cbc(1, &[7])]);
            c.add_bytecode_offsets(Some(&bs(&[8])));
            let n = NewExprent::new(obj("a/B"), Vec::<Exprent>::new(), Some(&bs(&[6])));
            n.set_constructor(Some(c.as_invocation()));
            n.0
        }
        "exit" => {
            ExitExprent::new(
                exit_exprent::Type::Return,
                Some(vbc(1, &[12])),
                Some(int()),
                Some(&bs(&[13])),
                None,
            )
            .0
        }
        "field" => {
            FieldExprent::new(
                "f".into(),
                "a/B".into(),
                false,
                Some(vbc(1, &[2])),
                fd("I"),
                Some(&bs(&[3])),
            )
            .0
        }
        "monitor" => {
            MonitorExprent::new(monitor_exprent::Type::Enter, vbc(1, &[0]), Some(&bs(&[1]))).0
        }
        "switch_head" => {
            let cases = vec![vec![Some(cbc(1, &[20])), Some(cbc(2, &[21]))], vec![None]];
            switch_head(vbc(1, &[3]), cases)
        }
        "annotation" => ann("a/A", &["x", "y"], vec![cbc(1, &[1]), cbc(2, &[2])]),
        "assert" => assert_of(vec![Some(vbc(1, &[4])), Some(cbc(1, &[5]))]),
        "pattern" => pat("a/R", vec![vbc(1, &[6]), pat("a/S", vec![vbc(2, &[7])])]),
        "yield" => yield_of(vbc(1, &[8]), int()),
        "const" => cbc(1, &[30]),
        "var" => vbc(1, &[31]),
        "switch" => switch_of(switch_stat(), true),
        _ => panic!("unknown bytecode-range case {label}"),
    }
}

fn run_bcr(label: &str) {
    let _g = common::install_default_context();
    reset();
    let e = bcr_subject(label);
    let mut values = BitSet::new();
    e.get_bytecode_range(Some(&mut values));
    let actual = vec![l!(
        "bcr",
        label,
        bits(Some(&values)),
        bits(e.get_bytecode().as_ref())
    )];
    check_label(&["bcr"], label, actual);
}

cases! { run_bcr:
    bytecode_range_assignment => "assignment",
    bytecode_range_array => "array",
    bytecode_range_function => "function",
    bytecode_range_if => "if",
    bytecode_range_invocation => "invocation",
    bytecode_range_new_array => "new_array",
    bytecode_range_new_object => "new_object",
    bytecode_range_exit => "exit",
    bytecode_range_field => "field",
    bytecode_range_monitor => "monitor",
    bytecode_range_switch_head => "switch_head",
    bytecode_range_annotation => "annotation",
    bytecode_range_assert => "assert",
    bytecode_range_pattern => "pattern",
    bytecode_range_yield => "yield",
    bytecode_range_const => "const",
    bytecode_range_var => "var",
    bytecode_range_switch => "switch",
}

// ---- per-kind queries ----

fn kq_subject(label: &str) -> Exprent {
    let boolean = VarType::VARTYPE_BOOLEAN;
    match label {
        "annotation" => ann("a/A", &[], vec![]),
        "array" => arr(varv(1, 0, arr_t(CodeType::Int, 1)), ci(0), int()),
        "array_null" => arr(ct(VarType::VARTYPE_NULL(), None), ci(0), long()),
        "array_2d" => arr(
            varv(
                1,
                0,
                VarType::new_value(CodeType::Object, 2, "java/lang/String"),
            ),
            ci(0),
            VarType::VARTYPE_OBJECT(),
        ),
        "assert" => assert_of(vec![Some(var(1))]),
        "assignment" => asg(varv(1, 0, int()), ci(1)),
        "assignment_join" => asg(varv(1, 0, long()), varv(2, 0, int())),
        "assignment_obj" => asg(
            varv(1, 0, obj("java/lang/Object")),
            varv(2, 0, obj("java/lang/String")),
        ),
        "const" => ci(70000),
        "exit" => ret(Some(var(1)), int()),
        "field_static" => sfield("f", "J"),
        "field_instance" => ifield("f", Some(var(1)), "Ljava/lang/String;"),
        "field_instance_inv" => ifield("f", Some(inv("m", "()La/B;", Some(var(1)), vec![])), "I"),
        "function_add" => fn_(FunctionType::Add, vec![var(1), ci(1)]),
        "function_cast" => fn_(
            FunctionType::Cast,
            vec![
                varv(1, 0, obj("java/lang/Object")),
                ct(obj("java/lang/String"), None),
            ],
        ),
        "function_cast_nocast" => {
            let f = fn_(
                FunctionType::Cast,
                vec![
                    varv(1, 0, obj("java/lang/Object")),
                    ct(obj("java/lang/String"), None),
                ],
            );
            f.as_function().set_needs_cast(false);
            f
        }
        "function_ternary" => fn_(FunctionType::Ternary, vec![cb(1), ci(1), ci(2)]),
        "function_ternary_obj" => fn_(
            FunctionType::Ternary,
            vec![
                varv(1, 0, boolean()),
                varv(2, 0, obj("java/lang/String")),
                ct(VarType::VARTYPE_NULL(), None),
            ],
        ),
        "function_and_bool" => fn_(
            FunctionType::And,
            vec![varv(1, 0, boolean()), varv(2, 0, boolean())],
        ),
        "function_and_int" => fn_(
            FunctionType::And,
            vec![varv(1, 0, boolean()), varv(2, 0, int())],
        ),
        "function_shl_long" => fn_(FunctionType::Shl, vec![varv(1, 0, long()), ci(1)]),
        "function_neg_double" => fn_(
            FunctionType::Neg,
            vec![varv(1, 0, VarType::VARTYPE_DOUBLE())],
        ),
        "function_pp" => {
            let f = fn_(FunctionType::Ppi, vec![var(1)]);
            f.as_function().set_implicit_type(Some(int()));
            f
        }
        "if" => ifx(if_exprent::Type::Icmpeq, var(1), var(2)),
        "invocation" => inv("m", "(I)J", Some(var(1)), vec![ci(1)]),
        "monitor" => monitor(monitor_exprent::Type::Enter, var(1)),
        "new_array" => new_arr(arr_t(CodeType::Int, 1), vec![ci(1)], vec![], false),
        "new_object" => new_obj("a/B", Some(inv("<init>", "()V", None, vec![]))),
        "pattern" => pat("a/R", vec![var(1)]),
        "switch" => SwitchExprent::new(switch_stat(), VarType::VARTYPE_STRING(), false, true).0,
        "switch_head" => switch_head(varv(1, 0, VarType::VARTYPE_CHAR()), vec![]),
        "var" => varv(1, 0, long()),
        "var_unknown" => VarExprent::new(1, None, None).0,
        "yield" => yield_of(var(1), VarType::VARTYPE_SHORT()),
        _ => panic!("unknown query case {label}"),
    }
}

#[test]
fn per_kind_type_precedence_and_use() {
    let _g = common::install_default_context();
    let actual = expected_where(|t, _| t == "kq")
        .iter()
        .map(|line| {
            let label = line.split(' ').nth(1).unwrap();
            reset();
            let e = kq_subject(label);
            let prec = if e.is_const() {
                "skip".to_string()
            } else {
                guard(|| e.get_precedence().to_string())
            };
            l!(
                "kq",
                label,
                guard(|| vt(&e.get_expr_type())),
                prec,
                guard(|| e.get_exprent_use().to_string())
            )
        })
        .collect();
    check_tag("kq", actual);
}

fn box_arg(spec: &str) -> Exprent {
    match spec {
        "c1" => ci(1),
        "c200" => ci(200),
        "c40000" => ci(40000),
        "vI" => varv(1, 0, int()),
        "vJ" => varv(1, 0, long()),
        "vZ" => varv(1, 0, VarType::VARTYPE_BOOLEAN()),
        _ => panic!("unknown boxing argument {spec}"),
    }
}

#[test]
fn invocation_boxing_calls() {
    let _g = common::install_default_context();
    let rows: [&[&str]; 17] = [
        &[
            "int_valueof_const",
            "java/lang/Integer",
            "valueOf",
            "s",
            "c40000",
        ],
        &[
            "char_valueof_bytechar",
            "java/lang/Character",
            "valueOf",
            "s",
            "c1",
        ],
        &[
            "short_valueof_shortchar",
            "java/lang/Short",
            "valueOf",
            "s",
            "c200",
        ],
        &[
            "byte_valueof_bytechar",
            "java/lang/Byte",
            "valueOf",
            "s",
            "c1",
        ],
        &["int_valueof_var", "java/lang/Integer", "valueOf", "s", "vI"],
        &["long_valueof_int", "java/lang/Long", "valueOf", "s", "vI"],
        &["long_valueof_long", "java/lang/Long", "valueOf", "s", "vJ"],
        &[
            "bool_valueof_bool",
            "java/lang/Boolean",
            "valueOf",
            "s",
            "vZ",
        ],
        &[
            "valueof_instance",
            "java/lang/Integer",
            "valueOf",
            "i",
            "vI",
        ],
        &[
            "valueof_two_params",
            "java/lang/Integer",
            "valueOf",
            "s",
            "vI",
            "vI",
        ],
        &["string_valueof", "java/lang/String", "valueOf", "s", "vI"],
        &["int_value", "java/lang/Integer", "intValue", "i"],
        &["int_value_on_long", "java/lang/Long", "intValue", "i"],
        &["long_value", "java/lang/Long", "longValue", "i"],
        &["char_value", "java/lang/Character", "charValue", "i"],
        &["int_value_static", "java/lang/Integer", "intValue", "s"],
        &[
            "int_value_param",
            "java/lang/Integer",
            "intValue",
            "i",
            "vI",
        ],
    ];
    let actual = rows
        .iter()
        .map(|row| {
            reset();
            let params: Vec<Exprent> = row[4..].iter().map(|s| box_arg(s)).collect();
            let ie = InvocationExprent::new();
            ie.set_name(row[2].into());
            ie.set_classname(row[1].into());
            ie.set_static(row[3] == "s");
            if !ie.is_static() {
                ie.set_instance(Some(varv(9, 0, obj(row[1]))));
            }
            ie.set_lst_parameters(params);
            l!(
                "box",
                row[0],
                b(ie.is_boxing_call()),
                b(ie.is_unboxing_call())
            )
        })
        .collect();
    check_tag("box", actual);
}

#[test]
fn function_unwrap_box() {
    let _g = common::install_default_context();
    reset();
    let unbox = InvocationExprent::new();
    unbox.set_name("intValue".into());
    unbox.set_classname("java/lang/Integer".into());
    unbox.set_instance(Some(
        FunctionExprent::new(
            FunctionType::Cast,
            vec![
                varv(1, 0, obj("java/lang/Object")),
                ct(obj("java/lang/Integer"), None),
            ],
            Some(&bs(&[1])),
        )
        .0,
    ));
    unbox.add_bytecode_offsets(Some(&bs(&[4])));
    let plain = InvocationExprent::new();
    plain.set_name("intValue".into());
    plain.set_classname("java/lang/Integer".into());
    plain.set_instance(Some(varv(2, 0, obj("java/lang/Integer"))));
    let f = fn_(FunctionType::Add, vec![unbox.0, plain.0, ci(3)]);
    let before = desc(f);
    f.as_function().unwrap_box();
    check_tag("unwrap", vec![l!("unwrap", "mixed", before, desc(f))]);
}

#[test]
fn var_names_versions_and_references() {
    let _g = common::install_default_context();
    reset();
    let a = var(3).as_var();
    let c = varv(3, 2, long()).as_var();
    let mut actual = vec![l!(
        "varname",
        "plain",
        a.get_name(),
        c.get_name(),
        var(10000).as_var().get_name()
    )];
    let v1 = varv(4, 1, int()).as_var();
    let v1b = varv(4, 1, long());
    let v2 = varv(4, 2, int());
    actual.push(l!(
        "varname",
        "equals_versions",
        b(v1.equals_versions(v1b)),
        b(v1.equals(v1b)),
        b(v1.equals_versions(v2)),
        b(v1.equals_versions(ci(4)))
    ));
    let x = var(5).as_var();
    let y = var(5).as_var();
    let tree = asg(x.0, fn_(FunctionType::Add, vec![y.0, var(6)]));
    actual.push(l!(
        "varname",
        "referenced",
        b(x.is_var_referenced_exp(tree, &[])),
        b(x.is_var_referenced_exp(tree, &[y])),
        b(var(7).as_var().is_var_referenced_exp(tree, &[])),
        b(x.is_var_referenced_exp(x.0, &[])),
        b(y.is_var_referenced_exp(tree, &[x]))
    ));
    check_tag("varname", actual);
}

#[test]
fn annotation_types() {
    let _g = common::install_default_context();
    reset();
    let names: [&[&str]; 5] = [&[], &["value"], &["x"], &["value", "x"], &["Value"]];
    let kinds: Vec<&str> = names
        .iter()
        .map(|n| {
            ann("a/A", n, vec![])
                .as_annotation()
                .get_annotation_type()
                .name()
        })
        .collect();
    check_tag("anntype", vec![l!("anntype", "all", kinds.join(","))]);
}
